# Decoders by serde name. Enums decode through the enum class.
_DECODERS: dict = {
    name: (_StableRow if name == "StableRow" else globals()[name]) for name in _ACCEPTS
}

# The serde names of all registry types, mapped to their Python classes.
TYPES: dict = {name: _DECODERS[name] for name in _ACCEPTS}
